function drawQueue(filter=queueFilter){queueFilter=filter;const chips=document.querySelectorAll('.chips button');if(chips.length<4)return;const all=openOrders.filter((order)=>order.status!=='closed'&&order.status!=='cancelled').length;const fresh=openOrders.filter((order)=>order.status==='open').length;const cooking=openOrders.filter((order)=>order.status==='in_progress').length;const ready=openOrders.filter((order)=>order.status==='ready').length;[all,fresh,cooking,ready].forEach((value,index)=>{const labels=['Все','Новый заказ','Готовится','Готово'];chips[index].textContent=`${labels[index]} ${value}`;chips[index].classList.toggle('active',chips[index].dataset.filter===queueFilter);chips[index].setAttribute('aria-pressed',String(chips[index].dataset.filter===queueFilter));});const list=document.querySelector('#queue-list');if(!list)return;const visible=openOrders.filter((order)=>{if(order.status==='closed'||order.status==='cancelled')return false;return queueFilter==='all'||order.status===queueFilter;});list.innerHTML=visible.length?visible.map((order)=>{const label=order.status==='ready'?'Готово':order.status==='in_progress'?'Готовится':'Новый заказ';const table=String(order.tableId||'').replace(/^table-/,'');const total=(order.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||item.price||0)*Number(item.quantity||1),0);return `<button type="button" class="queue-card" data-queue-table="${order.tableId||''}" data-queue-order="${order.id||''}"><span><b>Стол ${table||'—'}</b><small>${(order.items||[]).length} поз. · ${total.toLocaleString('ru-RU')} ₽${order.guestName?` · ${order.guestName}`:''}</small></span><em>${label}</em></button>`;}).join(''):'<div class="queue-empty">В этом разделе пока нет заказов</div>';}

