const defaultTableLayout=(zone,index)=>{const vip=/vip/i.test(String(zone?.name||''));const slots=vip?[[1,1,6,4],[7,1,6,4]]:[[1,1,3,2],[5,1,3,2],[9,1,3,2],[2,4,3,2],[6,4,3,2],[10,4,3,2],[1,7,3,2],[5,7,3,2],[9,7,3,2],[2,10,3,2],[6,10,3,2],[10,10,3,2]];const [x=1,y=1,w=3,h=2]=slots[index]||[1+((index%4)*3),1+Math.floor(index/4)*3,3,2];return{x,y,w,h};};
const floorPlacement=(table,zone,index)=>{const source=table?.layout&&typeof table.layout==='object'?table.layout:{};const fallback=defaultTableLayout(zone,index);const safe=(value,base,min,max)=>Number.isFinite(Number(value))?Math.min(max,Math.max(min,Math.round(Number(value)))):base;const rawX=Number(source.x);const rawY=Number(source.y);const rawW=Number(source.w??source.width);const rawH=Number(source.h??source.height);const x=Number.isFinite(rawX)?(rawX>12?Math.floor(rawX/190)+1:rawX):fallback.x;const y=Number.isFinite(rawY)?(rawY>20?Math.floor(rawY/125)+1:rawY):fallback.y;const w=Number.isFinite(rawW)&&source.width!==undefined?Math.max(2,Math.round(rawW/80)):rawW;const h=Number.isFinite(rawH)&&source.height!==undefined?Math.max(2,Math.round(rawH/45)):rawH;return{x:safe(x,fallback.x,1,12),y:safe(y,fallback.y,1,20),w:safe(w,fallback.w,2,12),h:safe(h,fallback.h,2,6),shape:['rectangle','square','circle','oval'].includes(source.shape)?source.shape:'rectangle',rotation:safe(source.rotation,0,-180,180)}};
const renderZone=(zone)=>{const serverTables=zone?.tables||[]; if(!serverTables.length){tables.innerHTML='<div class="queue-empty">В этой зоне пока нет столов</div>';return;} tables.classList.toggle('vip-floor',/vip/i.test(String(zone?.name||'')));serverTables.forEach((t)=>{tableMinimums[t.id]=Number(t.minimumOrderTotal||0);}); tables.innerHTML=serverTables.map((t,index)=>{const label=t.status==='occupied'?'Занят':t.status==='reserved'?`Бронь${t.reservation?.createdByName?` · ${t.reservation.createdByName}`:''}`:t.status==='awaiting_payment'?'Ожидает оплату':t.status==='blocked'?'Закрыт':'Свободен';const place=floorPlacement(t,zone,index);const style=`--table-x:${place.x};--table-y:${place.y};--table-w:${place.w};--table-h:${place.h};--table-rotation:${place.rotation}deg`;return `<button type="button" class="table shape-${place.shape} ${t.status==='occupied'?'busy':t.status==='reserved'?'reserve':t.status==='awaiting_payment'?'awaiting':t.status==='blocked'?'blocked':'free'} ${String(currentOrder?.tableId||'')===String(t.id)?'sel':''}" style="${style}" data-table="${t.id}" data-status="${t.status||'free'}" aria-label="${t.name}: ${label}" ${t.status==='blocked'?'disabled':''}><strong>${t.name.replace(/^Стол /,'')}</strong><em>${label}</em><small>${t.status==='reserved'&&t.reservation?.createdByRole?`Оформил: ${t.reservation.createdByRole}`:`${t.capacity||'2–4'} гостя`}</small></button>`}).join('');};
