document.querySelectorAll('aside nav button').forEach((button)=>button.addEventListener('click',()=>{
  document.querySelectorAll('aside nav button').forEach((item)=>{item.classList.remove('active');item.removeAttribute('aria-current');}); button.classList.add('active'); button.setAttribute('aria-current','page');
  const label=button.textContent.trim(); if(label.includes('Бронирования')) window.location.href='/reservations'; else if(label.includes('Склад')) window.location.href='/inventory'; else if(label.includes('Финансы')) window.location.href='/finance'; else if(label.includes('Заказы')||label.includes('Задачи')) { drawQueue(label.includes('Задачи')?'ready':'all'); document.querySelector('.queue')?.scrollIntoView({behavior:'smooth'}); notice(label.includes('Задачи')?'Показаны готовые задачи':'Показаны активные заказы'); } else document.querySelector('.tables')?.scrollIntoView({behavior:'smooth'});
}));
document.querySelector('#shift-toggle')?.addEventListener('click',async()=>{
  if(document.querySelector('#shift-toggle')?.disabled)return;const closing=Boolean(currentShift);const choice=await requestStaffAction({title:closing?'Закрыть смену':'Открыть смену',description:closing?'Сверьте фактический остаток в кассе перед закрытием.':'Укажите стартовый остаток в кассе.',submitLabel:closing?'Закрыть смену':'Открыть смену',fields:[{name:closing?'closingCash':'openingCash',label:closing?'Фактическая сумма':'Остаток в кассе',type:'number',min:0,step:.01,placeholder:'0',required:true}]});if(!choice)return;const key=closing?'closingCash':'openingCash';if(choice[key] === '' || choice[key] === undefined){notice('Укажите сумму наличных');return;}const amount=Number(choice[key]);if(!Number.isFinite(amount)||amount<0){notice('Сумма должна быть неотрицательной');return;}if(closing&&!window.confirm('Подтвердите чек-лист: заказы закрыты, касса сверена, складские операции завершены. Закрыть смену?'))return;if(closing){shiftApi({url:`/api/shifts/${currentShift.id}/close`,method:'POST',body:JSON.stringify({closingCash:amount,checklistConfirmed:true})}).then(()=>{currentShift=null;refreshShift();notice('Смена закрыта');}).catch(()=>notice('Не удалось закрыть смену'));return;}shiftApi({method:'POST',body:JSON.stringify({openingCash:amount})}).then((shift)=>{currentShift=shift;refreshShift();notice('Смена открыта');}).catch(()=>notice('Не удалось открыть смену'));
});
document.querySelectorAll('.tabs button').forEach((button)=>button.addEventListener('click',()=>{document.querySelectorAll('.tabs button').forEach((item)=>{item.classList.remove('selected');item.setAttribute('aria-selected','false');});button.classList.add('selected');button.setAttribute('aria-selected','true');const zone=serverZones.find((item)=>item.name.toLowerCase().includes(button.textContent.trim().toLowerCase()));if(zone)renderZone(zone);notice(`Зона «${button.textContent.trim()}» выбрана`);}));
document.querySelectorAll('.actions button').forEach((button)=>button.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала добавьте позицию в заказ');return;}
  const status=button.textContent.includes('бар')?'in_progress':'ready';
  apiJson(`/api/orders/${currentOrder.id}/status`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({status})}).then((saved)=>{Object.assign(currentOrder,saved);const active=openOrders.find((order)=>order.id===currentOrder.id);if(active)Object.assign(active,saved);drawQueue();notice(status==='in_progress'?'Заказ отправлен на бар':'Задача отправлена кальянщику');}).then(()=>refreshFloor()).catch(()=>notice('Не удалось передать заказ'));
}));
document.querySelector('#transfer-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала откройте заказ');return;}
  requestStaffAction({title:'Передать заказ',description:'Выберите стол, на который нужно перенести заказ.',submitLabel:'Передать заказ',fields:[{name:'table',label:'Номер стола',type:'number',min:1,max:99,step:1,placeholder:'1',required:true}]}).then((choice)=>{if(!choice)return;const table=Number(choice.table);if(!Number.isInteger(table)||table<1){notice('Укажите корректный номер стола');return;}const tableId=normalizeTableId(table);apiJson(`/api/orders/${currentOrder.id}/transfer`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({tableId})}).then((saved)=>{Object.assign(currentOrder,saved,{tableId});const active=openOrders.find((order)=>order.id===currentOrder.id);if(active)Object.assign(active,saved,{tableId});drawOrder(currentOrder);drawQueue();notice('Заказ передан на новый стол');}).then(()=>refreshFloor()).catch(()=>notice('Не удалось передать заказ'));});
});
document.querySelector('#print-receipt')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('Сначала добавьте позиции в заказ');return;}
  const escapeHtml=(value)=>String(value??'').replace(/[&<>\"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[char]));
  const rows=(currentOrder.items||[]).map((item)=>`<tr><td>${escapeHtml(item.name||'Позиция')}</td><td>${Number(item.quantity||1)}</td><td>${(Number(item.unitPrice||0)*Number(item.quantity||1)).toLocaleString('ru-RU')} ₽</td></tr>`).join('');
  const total=(currentOrder.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||0)*Number(item.quantity||1),0);
  const popup=window.open('','_blank','noopener,noreferrer,width=420,height=640');
  if(!popup){notice('Разрешите всплывающие окна для печати чека');return;}
  popup.document.write(`<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Чек ${escapeHtml(currentOrder.id)}</title><style>body{font:14px Arial,sans-serif;color:#111;padding:20px}h1{font-size:20px;margin:0 0 8px}p{margin:4px 0 14px;color:#555}table{width:100%;border-collapse:collapse}td{padding:7px 0;border-bottom:1px solid #ddd}td:nth-child(2),td:nth-child(3){text-align:right}.total{font-size:18px;font-weight:700;text-align:right;margin-top:18px}</style></head><body><h1>Территория · чек</h1><p>Заказ ${escapeHtml(currentOrder.id)} · ${new Date().toLocaleString('ru-RU')}</p><table>${rows}</table><div class="total">Итого: ${total.toLocaleString('ru-RU')} ₽</div><script>window.onload=()=>window.print();<\/script></body></html>`);
  popup.document.close();
});
document.querySelector('#split-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('В заказе нет позиций для разделения');return;}
  if(['closed','cancelled'].includes(currentOrder.status)){notice('Закрытый заказ нельзя разделить');return;}
  const lines=currentOrder.items.map((item,index)=>`${index+1}. ${item.name||'Позиция'} ×${item.quantity||1}`).join('\n');
  requestStaffAction({title:'Разделить заказ',description:`Выберите номера позиций через запятую.\n${lines}`,submitLabel:'Создать новый заказ',fields:[{name:'items',label:'Номера позиций',type:'text',placeholder:'1, 3',required:true}]}).then((choice)=>{if(!choice)return;const indexes=String(choice.items||'').split(',').map((value)=>Number(value.trim())-1).filter((value)=>Number.isInteger(value)&&value>=0&&value<currentOrder.items.length);const itemIds=[...new Set(indexes)].map((index)=>currentOrder.items[index].id);if(!itemIds.length){notice('Позиции не выбраны');return;}apiJson(`/api/orders/${currentOrder.id}/split`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({itemIds})}).then((target)=>{currentOrder.items=currentOrder.items.filter((item)=>!itemIds.includes(item.id));openOrders.push(target);drawOrder(currentOrder);drawQueue();return refreshFloor().then(()=>loadOrders()).then(()=>{notice('Новый заказ создан');});}).catch(()=>notice('Не удалось разделить заказ'));});
});
const paymentModal=document.querySelector('#payment-modal'); const paymentForm=document.querySelector('#payment-form');
const paymentInputs=['cash','card','qr'].map((method)=>document.querySelector(`#payment-${method}`)).filter(Boolean);
const paymentDue=()=>{const subtotal=(currentOrder?.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||item.price||0)*Number(item.quantity||1),0);return Math.max(subtotal-localApprovedDiscountTotal(currentOrder?.id,subtotal),Number(currentOrder?.minimumOrderTotal||0));};
const refreshPaymentRemainder=()=>{const due=paymentDue();const paid=paymentInputs.reduce((sum,input)=>sum+Math.max(0,Number(input.value||0)),0);const remainder=document.querySelector('#payment-remaining');if(remainder)remainder.textContent=`Остаток ${Math.max(0,due-paid).toLocaleString('ru-RU')} ₽`;};
paymentInputs.forEach((input)=>input.addEventListener('input',refreshPaymentRemainder));
document.querySelector('#payment-close')?.addEventListener('click',()=>paymentModal?.classList.remove('open'));
paymentModal?.addEventListener('click',(event)=>{if(event.target===paymentModal)paymentModal.classList.remove('open');});
document.querySelector('#split-payment')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('Сначала добавьте позиции в заказ');return;}
  const due=paymentDue(); const dueEl=document.querySelector('#payment-due'); if(dueEl)dueEl.textContent=`${due.toLocaleString('ru-RU')} ₽`; paymentInputs.forEach((input)=>{input.value='0';}); const message=document.querySelector('#payment-message'); if(message)message.textContent=''; refreshPaymentRemainder(); paymentModal?.classList.add('open'); paymentInputs[0]?.focus();
});
paymentForm?.addEventListener('submit',async(event)=>{
  event.preventDefault();const submit=paymentForm.querySelector('[type=submit]');if(submit?.disabled)return;submit&&(submit.disabled=true); const due=paymentDue(); const entries=[['cash','Наличные'],['card','Карта'],['qr','QR']].map(([method])=>({method,amount:Number(document.querySelector(`#payment-${method}`)?.value||0)})).filter((entry)=>entry.amount>0); const total=entries.reduce((sum,entry)=>sum+entry.amount,0); const message=document.querySelector('#payment-message'); if(!entries.length||total>due+0.01){if(message)message.textContent=total>due?'Сумма платежей больше суммы заказа.':'Укажите хотя бы один способ оплаты.';submit&&(submit.disabled=false);return;} try { let paid=0; for(const entry of entries){const result=await apiJson(`/api/orders/${currentOrder.id}/payments`,{method:'POST',headers:orderHeaders(),body:JSON.stringify(entry)});paid=Number(result.paid||paid+entry.amount);currentOrder.paid=paid;currentOrder.remaining=Number(result.remaining||0);currentOrder.status=result.closed?'closed':currentOrder.status;} paymentModal.classList.remove('open'); if (paid>=due) { currentOrder.status='closed'; const active=openOrders.find((order)=>order.id===currentOrder.id); if(active) active.status='closed'; drawQueue(); } notice(paid>=due?'Заказ оплачен частями':'Платёж сохранён, остаток '+(due-paid).toLocaleString('ru-RU')+' ₽'); if (paid>=due) { currentOrder=null; drawOrder({items:[]}); await loadOrders(); await refreshFloor(); } } catch (_) {if(message)message.textContent='Не удалось записать платеж. Проверьте данные и повторите.';} finally {submit&&(submit.disabled=false);}
});
document.querySelectorAll('.order-tabs button').forEach((tab)=>tab.addEventListener('click',()=>{
  if(!currentOrder){notice('Сначала выберите стол');return;}
  if(tab.textContent.trim()==='Гости'){apiJson('/api/clients').then((payload)=>{const options=[{value:'',label:'Без привязки'}].concat((payload.items||[]).map((client)=>({value:client.id,label:`${client.name}${client.telegram?` · ${client.telegram}`:''}`})));return requestStaffAction({title:'Гость в заказе',description:'Выберите профиль гостя или сохраните новый контакт. История и предпочтения будут доступны в карточке гостя.',submitLabel:'Сохранить гостя',fields:[{name:'guests',label:'Количество гостей',type:'number',min:1,step:1,value:currentOrder.guests||2,placeholder:'2',required:true},{name:'clientId',label:'Профиль гостя',type:'select',options,value:currentOrder.clientId||''},{name:'guestName',label:'Имя гостя, если профиль не выбран',type:'text',value:currentOrder.guestName||'',placeholder:'Имя и фамилия'},{name:'phone',label:'Телефон, если профиль не выбран',type:'tel',value:currentOrder.guestPhone||'',placeholder:'+7 (___) ___-__-__'}]});}).then((choice)=>{if(!choice)return;const guests=Number(choice.guests);if(!Number.isInteger(guests)||guests<1){notice('Количество гостей должно быть не меньше одного');return;}const payload={clientId:String(choice.clientId||'').trim()||null,guestName:String(choice.guestName||'').trim(),phone:String(choice.phone||'').trim()};apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify(payload)}).then((saved)=>{currentOrder.guests=guests;currentOrder.clientId=saved.clientId||String(choice.clientId||'').trim()||null;currentOrder.guestName=saved.guestName||payload.guestName;currentOrder.guestPhone=saved.phone||payload.phone;drawOrder(currentOrder);notice('Гость привязан к заказу');}).catch(()=>notice('Не удалось сохранить гостя'));});return;}
  requestStaffAction({title:'Заметка к заказу',description:'Комментарий будет виден сотрудникам, которые обслуживают этот заказ.',submitLabel:'Сохранить заметку',fields:[{name:'notes',label:'Комментарий',type:'textarea',value:currentOrder.notes||'',placeholder:'Например: без мяты, подать после кальяна'}]}).then((choice)=>{if(!choice)return;const value=String(choice.notes||'').trim();apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({notes:value})}).then(()=>{currentOrder.notes=value;notice(value?'Заметка сохранена':'Заметка очищена');}).catch(()=>notice('Не удалось сохранить заметку'));});
}));
